const ZONE = 'Africa/Abidjan';
const now = $now.setZone(ZONE);
const debut = now.minus({ days: 6 }).setLocale('fr').toFormat('dd MMMM');
const fin = now.setLocale('fr').toFormat('dd MMMM');

// Les deux canaux ne parlent pas la meme langue de balisage.
//
// Telegram, quand on lui demande d'analyser, lit du HTML : une esperluette
// dans un nom de produit fait echouer l'envoi entier. On echappe donc.
const ech = (v) => String(v ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .trim();

// WhatsApp met en gras entre asterisques, sans jamais echouer : le risque n'y
// est que cosmetique. On retire les caracteres qui deformeraient la mise en
// forme.
const net = (v) => String(v ?? '').replace(/[*_~`]/g, '').trim();

const fcfa = (n) => Number(n || 0).toLocaleString('fr-FR');

const rep = $('Activite de la semaine').first().json || {};
const boutiques = rep.boutiques || [];
const plats = rep.plats || [];

if (!boutiques.length) return [];

const platsParBoutique = new Map();
for (const p of plats) {
  if (!platsParBoutique.has(p.slug)) platsParBoutique.set(p.slug, []);
  platsParBoutique.get(p.slug).push(p);
}

// Ou joindre chaque marchand : un bilan ne part jamais vers le chat d'une
// autre boutique que celle dont il parle.
const annuaire = {};
for (const m of ($('Lire le registre').first().json.marchands) || []) {
  annuaire[String(m.id || '').trim()] = m;
}

const sorties = [];

for (const b of boutiques) {
  const slug = String(b.slug || '').trim();
  const m = annuaire[slug] || {};

  const top = (platsParBoutique.get(b.slug) || [])
    .map((p) => ({ brut: String(p.produit ?? ''), q: p.quantite }))
    .filter((p) => p.brut.trim())
    .slice(0, 5);

  const satisfaction = b.avis > 0
    ? `${String(b.note_moyenne).replace('.', ',')}/5 (${b.avis} avis)`
    : null;

  // --- Variante Telegram : HTML, tout le variable echappe.
  let tg = `📈 <b>RAPPORT HEBDOMADAIRE</b>\n🗓️ ${ech(debut)} → ${ech(fin)}\n`;
  tg += `\n🏪 <b>${ech(b.boutique_nom)}</b>\n\n`;
  tg += `💰 CA : <b>${ech(fcfa(b.ca))} FCFA</b>\n`;
  tg += `🛒 Commandes : <b>${ech(b.commandes)}</b> · livrees : <b>${ech(b.livrees)}</b>\n`;
  tg += `🧺 Panier moyen : <b>${ech(fcfa(b.panier_moyen))} FCFA</b>\n`;
  if (top.length) {
    tg += `\n🍽️ <b>Top 5 produits</b>\n`;
    top.forEach((p, i) => { tg += `${i + 1}. ${ech(p.brut)} : <b>${ech(p.q)}</b>\n`; });
  }
  tg += `\n⭐ Satisfaction : `;
  tg += satisfaction ? `<b>${ech(satisfaction)}</b>\n` : `aucun avis cette semaine\n`;
  tg += `\n━━━━━━━━\nDjiguiFlow 🤖`;

  // --- Variante WhatsApp : asterisques natifs, rien a echapper.
  let wa = `📈 *RAPPORT HEBDOMADAIRE*\n🗓️ ${debut} → ${fin}\n`;
  wa += `\n🏪 *${net(b.boutique_nom)}*\n\n`;
  wa += `💰 CA : *${fcfa(b.ca)} FCFA*\n`;
  wa += `🛒 Commandes : *${b.commandes}* · livrees : *${b.livrees}*\n`;
  wa += `🧺 Panier moyen : *${fcfa(b.panier_moyen)} FCFA*\n`;
  if (top.length) {
    wa += `\n🍽️ *Top 5 produits*\n`;
    top.forEach((p, i) => { wa += `${i + 1}. ${net(p.brut)} : *${p.q}*\n`; });
  }
  wa += `\n⭐ Satisfaction : `;
  wa += satisfaction ? `*${satisfaction}*\n` : `aucun avis cette semaine\n`;
  wa += `\n━━━━━━━━\nDjiguiFlow 🤖`;

  sorties.push({ json: {
    slug,
    message_telegram: tg,
    message_whatsapp: wa,
    telegram: String(m.telegramMarchand || '').trim(),
    whatsapp: String(m.whatsapp || '').trim(),
    // Le journal d'envoi ecrit dans le classeur de l'appelant : sans lui, il
    // n'ecrit nulle part, ce qui vaut mieux que d'ecrire au hasard.
    sheet_document_id: String(m.sheetId || '').trim(),
  } });
}

return sorties;

